{
  "name": "PI E-709 压电纳米定位控制器",
  "name_en": "PI E-709 Piezo Nanopositioning Controller",
  "manufacturer": "Physik Instrumente (PI)",
  "description": "用于驱动压电纳米定位器的运动控制器，可进行绝对/相对位移、伺服开关、位置读取以及控制状态与固件信息查询，常用于显微镜精密调焦与高分辨定位实验。",
  "description_en": "A motion controller for piezo nanopositioners, supporting absolute/relative moves, servo enable control, position readback, and queries of control status and firmware information. It is commonly used for precision microscope focusing and high-resolution positioning experiments.",
  "actions": [
    {
      "action_name": "auto-ReInit",
      "description": "重新初始化压电控制器并停止波形输出。",
      "description_en": "Reinitialize the piezo controller and stop waveform output."
    },
    {
      "action_name": "auto-SetServo",
      "description": "设置压电控制器的伺服开关状态。",
      "description_en": "Set the servo on/off state of the piezo controller."
    },
    {
      "action_name": "auto-MoveTo",
      "description": "将指定通道移动到目标位置。",
      "description_en": "Move the specified channel to a target position."
    },
    {
      "action_name": "auto-MoveRel",
      "description": "使指定通道相对当前位置移动一定增量。",
      "description_en": "Move the specified channel by a relative increment from its current position."
    },
    {
      "action_name": "auto-GetPos",
      "description": "读取指定通道的当前位置。",
      "description_en": "Read the current position of the specified channel."
    },
    {
      "action_name": "auto-GetControlReady",
      "description": "查询控制器是否处于就绪状态。",
      "description_en": "Query whether the controller is in a ready state."
    },
    {
      "action_name": "auto-GetChannelObject",
      "description": "查询通道对象参数。",
      "description_en": "Query the channel object parameter."
    },
    {
      "action_name": "auto-GetChannelPhase",
      "description": "查询通道相位参数。",
      "description_en": "Query the channel phase parameter."
    },
    {
      "action_name": "auto-GetMin",
      "description": "查询指定通道的最小位置范围。",
      "description_en": "Query the minimum position range of the specified channel."
    },
    {
      "action_name": "auto-GetMax",
      "description": "查询指定通道的最大位置范围。",
      "description_en": "Query the maximum position range of the specified channel."
    },
    {
      "action_name": "auto-GetFirmwareVersion",
      "description": "查询控制器固件版本。",
      "description_en": "Query the controller firmware version."
    }
  ],
  "tag_hints": [
    "piezo positioning",
    "nanopositioning",
    "closed-loop servo",
    "serial motion control",
    "microscope focus control",
    "waveform output",
    "precision stage control"
  ]
}

